import pandas as pd
import numpy as np

# Load the data
df = pd.read_csv('chunks_csv/changespillover/changespillover_no2crime_crime_second_half_2014_to_first_half_2015.csv')
adjacency_df = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Calculate the change in Recorded Crime per 10,000 residents
df['change'] = df['first_half_2015_value'] - df['second_half_2014_value']

# Create a dictionary to map boroughs to their neighbors
neighbor_dict = {}
for index, row in adjacency_df.iterrows():
    if row['borough'] not in neighbor_dict:
        neighbor_dict[row['borough']] = [row['neighbor']]
    else:
        neighbor_dict[row['borough']].append(row['neighbor'])

# Create a list to store the neighbors of each borough
neighbors = []
for key in neighbor_dict:
    neighbors.extend(neighbor_dict[key])

# Create a dictionary to map each borough to its neighbors' changes
neighbor_changes = {}
for index, row in df.iterrows():
    if row['borough'] not in neighbor_changes:
        neighbor_changes[row['borough']] = []
    for neighbor in neighbor_dict[row['borough']]:
        if neighbor in df['borough'].values:
            neighbor_changes[row['borough']].append(df.loc[df['borough'] == neighbor, 'change'].values[0])

# Calculate the average change of each borough's neighbors
neighbor_avg_changes = {}
for key in neighbor_changes:
    neighbor_avg_changes[key] = np.mean(neighbor_changes[key])

# Calculate the correlation between each borough's change and its neighbors' average change
correlation = {}
for index, row in df.iterrows():
    if row['borough'] not in correlation:
        correlation[row['borough']] = np.corrcoef([row['change'], neighbor_avg_changes[row['borough']]])[0][1]

# Calculate the test statistic (Moran's I)
test_statistic = 0
for key in correlation:
    test_statistic += correlation[key]
test_statistic /= len(correlation)

# Calculate the p-value using a permutation test
p_value = 0
for _ in range(500):
    # Shuffle the changes of the neighbors
    shuffled_neighbor_changes = np.random.permutation(neighbor_changes.values())

    # Calculate the correlation between each borough's change and its shuffled neighbors' average change
    shuffled_correlation = {}
    for key in neighbor_changes:
        shuffled_correlation[key] = np.corrcoef([df.loc[df['borough'] == key, 'change'].values[0], np.mean(shuffled_neighbor_changes[neighbor_changes[key].index(key)])])[0][1]

    # Calculate the test statistic (Moran's I) for the shuffled data
    shuffled_test_statistic = 0
    for key in shuffled_correlation:
        shuffled_test_statistic += shuffled_correlation[key]
    shuffled_test_statistic /= len(shuffled_correlation)

    # Update the p-value
    if shuffled_test_statistic >= test_statistic:
        p_value += 1

# Calculate the final p-value
p_value /= 500

# Print the final answer
print(f"FINAL ANSWER: {'CLUSTERED' if p_value < 0.05 else 'NOT CLUSTERED'} (test statistic = {test_statistic}, p = {p_value})")
